import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import {
  Brain,
  Scan,
  LineChart,
  Database,
  ArrowRight,
  ShieldCheck,
  CheckCircle2,
  AlertTriangle,
  Cpu,
  Layers,
  Sparkles,
} from 'lucide-react';
import { api } from '../api/client';
import { DatasetInfoResponse, HealthResponse, ModelInfoResponse } from '../types';
import { useLanguage } from '../context/LanguageContext';
import DisclaimerBanner from '../components/common/DisclaimerBanner';

const HomePage: React.FC = () => {
  const { t } = useLanguage();
  const [health, setHealth] = useState<HealthResponse | null>(null);
  const [modelInfo, setModelInfo] = useState<ModelInfoResponse | null>(null);
  const [datasetInfo, setDatasetInfo] = useState<DatasetInfoResponse | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadDashboardData = async () => {
      try {
        const [healthRes, modelRes, datasetRes] = await Promise.allSettled([
          api.getHealth(),
          api.getModelInfo(),
          api.getDatasetInfo(),
        ]);

        if (healthRes.status === 'fulfilled') setHealth(healthRes.value);
        if (modelRes.status === 'fulfilled') setModelInfo(modelRes.value);
        if (datasetRes.status === 'fulfilled') setDatasetInfo(datasetRes.value);
      } catch (err) {
        console.error('Error fetching dashboard data:', err);
      } finally {
        setLoading(false);
      }
    };

    loadDashboardData();
  }, []);

  const workflowSteps = [
    {
      step: '01',
      title: t('home.step1_title'),
      desc: t('home.step1_desc'),
      icon: Database,
    },
    {
      step: '02',
      title: t('home.step2_title'),
      desc: t('home.step2_desc'),
      icon: Layers,
    },
    {
      step: '03',
      title: t('home.step3_title'),
      desc: t('home.step3_desc'),
      icon: Cpu,
    },
    {
      step: '04',
      title: t('home.step4_title'),
      desc: t('home.step4_desc'),
      icon: LineChart,
    },
  ];

  return (
    <div className="space-y-8 max-w-7xl mx-auto">
      {/* Hero Section */}
      <section className="relative overflow-hidden rounded-3xl bg-gradient-to-b from-slate-900 via-slate-900/90 to-slate-950 border border-slate-800 p-6 sm:p-10 shadow-2xl">
        <div className="absolute top-0 right-0 -mt-12 -mr-12 w-96 h-96 bg-teal-500/10 rounded-full blur-3xl pointer-events-none" />
        <div className="relative z-10 max-w-3xl space-y-6">
          <div className="inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-teal-500/10 border border-teal-500/20 text-xs font-semibold text-teal-300">
            <Sparkles className="w-3.5 h-3.5 text-teal-400" />
            <span>{t('common.educational_badge')}</span>
          </div>

          <h1 className="text-3xl sm:text-5xl font-extrabold text-white tracking-tight leading-tight">
            {t('home.hero_title')}
          </h1>

          <p className="text-sm sm:text-base text-slate-300 leading-relaxed">
            {t('home.hero_desc')}
          </p>

          <div className="flex flex-wrap items-center gap-3 pt-2">
            <Link
              to="/tasks"
              className="inline-flex items-center space-x-2 px-5 py-2.5 rounded-xl bg-gradient-to-r from-teal-500 to-teal-600 hover:from-teal-400 hover:to-teal-500 text-slate-950 font-bold text-sm shadow-lg shadow-teal-500/20 transition-all hover:scale-[1.02]"
            >
              <Layers className="w-4 h-4" />
              <span>Select Research Condition (5 Tasks)</span>
              <ArrowRight className="w-4 h-4 ml-1" />
            </Link>

            <Link
              to="/scans"
              className="inline-flex items-center space-x-2 px-5 py-2.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 font-medium text-sm border border-slate-700 transition-colors"
            >
              <Scan className="w-4 h-4 text-teal-400" />
              <span>{t('home.open_scan_center')}</span>
            </Link>

            <Link
              to="/evaluation"
              className="inline-flex items-center space-x-2 px-5 py-2.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 font-medium text-sm border border-slate-700 transition-colors"
            >
              <LineChart className="w-4 h-4" />
              <span>{t('home.view_evaluation')}</span>
            </Link>
          </div>
        </div>
      </section>

      {/* Safety Notice */}
      <DisclaimerBanner />

      {/* Live System Status Cards */}
      <section className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {/* Research Tasks Card */}
        <div className="p-5 rounded-2xl bg-slate-900/60 border border-slate-800 space-y-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-2 text-slate-200 font-semibold text-sm">
              <Layers className="w-4 h-4 text-teal-400" />
              <span>Modular Tasks</span>
            </div>
            <span className="text-xs px-2.5 py-0.5 rounded-full font-medium bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
              1 Active • 4 In Setup
            </span>
          </div>
          <div className="text-xs text-slate-400 space-y-1.5 font-mono">
            <p>Ready: Brain Tumor Classification</p>
            <p>Setup: Alzheimer's, MS, Stroke</p>
            <p className="text-teal-400 hover:underline">
              <Link to="/tasks">View All Task Specifications →</Link>
            </p>
          </div>
        </div>

        {/* Model Status Card */}
        <div className="p-5 rounded-2xl bg-slate-900/60 border border-slate-800 space-y-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-2 text-slate-200 font-semibold text-sm">
              <Cpu className="w-4 h-4 text-teal-400" />
              <span>Tumor CNN Model</span>
            </div>
            <span
              className={`text-xs px-2.5 py-0.5 rounded-full font-medium ${
                modelInfo?.loaded
                  ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20'
                  : 'bg-amber-500/10 text-amber-400 border border-amber-500/20'
              }`}
            >
              {modelInfo?.training_status || (loading ? 'Checking...' : 'Not loaded')}
            </span>
          </div>
          <div className="text-xs text-slate-400 space-y-1.5 font-mono">
            <p>Architecture: Custom 3-Block CNN</p>
            <p>Target Modality: Brain MRI (RGB 224×224)</p>
            <p>Parameters: 304,484 Trainable</p>
          </div>
        </div>

        {/* Dataset Status Card */}
        <div className="p-5 rounded-2xl bg-slate-900/60 border border-slate-800 space-y-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-2 text-slate-200 font-semibold text-sm">
              <Database className="w-4 h-4 text-cyan-400" />
              <span>Dataset Overview</span>
            </div>
            <span className="text-xs px-2.5 py-0.5 rounded-full font-medium bg-cyan-500/10 text-cyan-400 border border-cyan-500/20">
              {datasetInfo?.total_images ? `${datasetInfo.total_images} Scans` : 'Dataset Available'}
            </span>
          </div>
          <div className="text-xs text-slate-400 space-y-1.5 font-mono">
            <p>Directory: /dataset (3-way split)</p>
            <p>Held-out Test: 40 scans (unseen)</p>
            <p>Zero Patient Data Leakage</p>
          </div>
        </div>
      </section>

      {/* Deep Learning Workflow Section */}
      <section className="space-y-4">
        <div className="space-y-1">
          <h2 className="text-xl font-bold text-white tracking-tight">
            {t('home.workflow_title')}
          </h2>
          <p className="text-xs text-slate-400">
            Step-by-step pipeline demonstrating machine learning best practices in medical imaging research.
          </p>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {workflowSteps.map((step) => {
            const Icon = step.icon;
            return (
              <div
                key={step.step}
                className="p-5 rounded-2xl bg-slate-900/40 border border-slate-800/80 hover:border-teal-500/30 transition-all space-y-3 group"
              >
                <div className="flex items-center justify-between">
                  <span className="font-mono text-xs font-bold text-teal-400/60 group-hover:text-teal-400 transition-colors">
                    {step.step}
                  </span>
                  <div className="p-2 rounded-xl bg-slate-800/60 text-teal-400 group-hover:bg-teal-500/10 transition-colors">
                    <Icon className="w-4 h-4" />
                  </div>
                </div>
                <div className="space-y-1">
                  <h3 className="text-sm font-semibold text-slate-200">
                    {step.title}
                  </h3>
                  <p className="text-xs text-slate-400 leading-relaxed">
                    {step.desc}
                  </p>
                </div>
              </div>
            );
          })}
        </div>
      </section>
    </div>
  );
};

export default HomePage;
